import { useId, type ReactNode } from 'react';
import './NavigationSidebar.css';
type Row = { id: string; label: string; href: string; icon?: ReactNode; disabled?: boolean };
type Section = { id: string; label: string; rows: Row[] };
export function NavigationSidebar({ selectedId, sections, summary, onSettings, onHelp }: { selectedId: string; sections: [Section, Section]; summary: ReactNode; onSettings: () => void; onHelp: () => void }) {
 const uid = useId();
 return <aside className="navigation-sidebar"><nav aria-label="Workspace navigation">
 {sections.map(section => <section key={section.id} aria-labelledby={uid + section.id}>
 <h2 id={uid + section.id}>{section.label}</h2><ul>{section.rows.map(row => <li key={row.id}>{row.disabled
 ? <span className="navigation-row" aria-disabled="true"><span aria-hidden="true">{row.icon}</span><span>{row.label} (unavailable)</span></span>
 : <a className="navigation-row" href={row.href} aria-current={row.id === selectedId ? 'page' : undefined}><span aria-hidden="true">{row.icon}</span><span>{row.label}</span></a>
 }</li>)}</ul></section>)}
 </nav><section className="workspace-summary" aria-label="Workspace summary">{summary}</section>
 <footer><button onClick={onSettings}>Settings</button><button onClick={onHelp}>Help</button></footer></aside>;
}

