.navigation-sidebar{--gutter:12px;display:flex;flex-direction:column;gap:20px;padding:var(--gutter);width:100%;box-sizing:border-box;min-width:0}
.navigation-sidebar section h2{font-size:.8rem;margin:0;padding:6px 10px}
.navigation-sidebar ul{list-style:none;margin:0;padding:0}
.navigation-row{display:grid;grid-template-columns:20px minmax(0,1fr);align-items:center;gap:8px;padding:8px 10px;text-decoration:none;color:inherit;border-radius:6px;overflow-wrap:anywhere}
.navigation-row[aria-current=page]{background:#e1eaff;font-weight:700;box-shadow:inset 3px 0 #255ec9}
.navigation-row[aria-disabled=true]{color:#666}
.workspace-summary{padding:10px;border:1px solid #b9bec8;border-radius:6px;overflow-wrap:anywhere}
.navigation-sidebar footer{margin-top:auto;display:flex;flex-wrap:wrap;gap:8px}
.navigation-sidebar button{padding:6px 10px}
.navigation-sidebar :focus-visible{outline:2px solid #255ec9;outline-offset:2px}
